This wrapper truncates the greeting and sometimes crashes. The C side is:

```c
int greet(char *buf, size_t cap, const char *name) {
  return snprintf(buf, cap, "hello, %s", name);
}
```

```julia
# partial
function greet(name)
    buf = " " ^ 8
    @ccall libdemo.greet(buf::Cstring, 8::Csize_t, name::Cstring)::Cint
    return buf
end
```

A `Vector{Float64}` passes as `Ptr{Float64}`; outputs go through `Ref`s. C source:

```c
void sum_and_max(const double *v, size_t n, double *sum, double *mx) {
  *sum = 0; *mx = v[0];
  for (size_t i = 0; i < n; i++) { *sum += v[i]; if (v[i] > *mx) *mx = v[i]; }
}
```

```julia
# partial
const libdemo = "./libdemo"

function sum_and_max(v::Vector{Float64})
    isempty(v) && throw(ArgumentError("v must be non-empty"))   # C reads v[0] unconditionally
    s = Ref{Cdouble}()
    m = Ref{Cdouble}()
    @ccall libdemo.sum_and_max(v::Ptr{Float64}, length(v)::Csize_t, s::Ptr{Cdouble}, m::Ptr{Cdouble})::Cvoid
    return s[], m[]
end

sum_and_max([3.0, 9.0, 1.0])
```

`Ref{Cdouble}()` allocates uninitialized storage that C fills in; `s[]` reads it. The `Vector` and the `Ref`s are rooted for the call by the `ccall` conversion. Validate arguments the C code cannot (empty input here) on the Julia side.

